package main

import (
	"context"
	"encoding/base64"
	"fmt"
	"log"
	"math/big"
	"strings"
	"time"

	"cosmossdk.io/x/auth/tx"
	"github.com/cosmos/cosmos-sdk/crypto/keys/secp256k1"
	sdk "github.com/cosmos/cosmos-sdk/types"
	signing "github.com/cosmos/cosmos-sdk/types/tx/signing"
	authtx "github.com/cosmos/cosmos-sdk/x/auth/tx"
	"github.com/cosmos/solidity-ibc-eureka/packages/go-abigen/ics20transfer"
	"github.com/ethereum/go-ethereum/accounts/abi"
	"github.com/ethereum/go-ethereum/common"
	"github.com/srdtrk/solidity-ibc-eureka/e2e/v8/chainconfig"

	cmthttprpc "github.com/cometbft/cometbft/v2/rpc/client/http"
	clienttypes "github.com/cosmos/ibc-go/v10/modules/core/02-client/types"
)

func main() {
	msgSendPacket := ics20transfer.IICS20TransferMsgsSendTransferMsg{
		Denom:            common.HexToAddress("0x63e6dde6763c3466c7b45be880f7ee5dc2ca3e25"),
		Amount:           big.NewInt(1000000000000),
		Receiver:         "cosmos1wj9awcgsfuusmfwrda83v7qxuhls0kzerzran9",
		TimeoutTimestamp: uint64(time.Now().Add(30 * time.Minute).Unix()),
		SourceClient:     "cosmoshub-1",
		Memo:             "",
	}

	// print(uint64(time.Now().Add(30 * time.Minute).Unix()))

	ics20transferAbi, err := abi.JSON(strings.NewReader(ics20transfer.ContractABI))
	if err != nil {
		panic(fmt.Sprintf("Failed to parse ABI: %v", err))
	}

	encodedMsg, err := ics20transferAbi.Pack("sendTransfer", msgSendPacket)
	if err != nil {
		panic(fmt.Sprintf("Failed to pack message: %v", err))
	}
	_ = encodedMsg

	data := ""

	decoded, err := base64.StdEncoding.DecodeString(data)
	if err != nil {
		panic("failed to decode base64")
	}

	encodingConfig := chainconfig.SDKEncodingConfig()

	var msg clienttypes.MsgUpdateClient
	if err := encodingConfig.Codec.Unmarshal(decoded, &msg); err != nil {
		log.Fatalf("failed to unmarshal Any: %v", err)
	}

	// insert private key here
	priv := secp256k1.PrivKey{Key: privBytes}
	signerAddr := sdk.AccAddress(priv.PubKey().Address())

	txCfg := tx.NewTxConfig(encodingConfig.Codec, authtx.DefaultSignModes)
	txBuilder := txCfg.NewTxBuilder()
	txBuilder.SetMsgs(&msg)
	txBuilder.SetGasLimit(200_000)
	txBuilder.SetFeeAmount(fee) // set fee here

	// 4) Produce sign bytes
	signerData := txsigning.SignerData{
		ChainID:       chainID,
		AccountNumber: accNumber,
		Sequence:      sequence,
	}
	signBz, err := txCfg.SignModeHandler().GetSignBytes(
		context.Background(), txsigning.SignMode_SIGN_MODE_DIRECT, signerData, txBuilder.GetTx(),
	)
	if err != nil {
		log.Fatalf("failed to set signature: %v", err)
	}

	// 5) Sign with your private key
	sigRaw, err := priv.Sign(signBz)
	if err != nil {
		log.Fatalf("failed to sign: %v", err)
	}

	// 6) Set the final signature
	sigV2 := signing.SignatureV2{
		PubKey:   priv.PubKey(),
		Data:     &signing.SingleSignatureData{SignMode: signing.SignMode_SIGN_MODE_DIRECT, Signature: sigRaw},
		Sequence: sequence,
	}
	if err := txBuilder.SetSignatures(sigV2); err != nil {
		log.Fatalf("failed to set signature: %v", err)
	}

	txBytes, err := txCfg.TxEncoder()(txBuilder.GetTx())
	if err != nil {
		log.Fatalf("failed to build tx: %v", err)
	}

	// Your node’s RPC endpoint (default :26657)
	c, err := cmthttprpc.NewWithTimeout("http://127.0.0.1:26657", 10) // seconds
	if err != nil {
		panic(err)
	}

	resCommit, err := c.BroadcastTxCommit(context.Background(), txBytes)
	fmt.Println(resCommit)
}
